 const fitTree=useCallback(()=>{const viewport=treeRef.current;if(!viewport)return;const scale=clampScale(Math.min((viewport.clientWidth-20)/PRESTIGE_CANVAS.width,(viewport.clientHeight-20)/PRESTIGE_CANVAS.height));setMapView({scale,x:(viewport.clientWidth-PRESTIGE_CANVAS.width*scale)/2,y:(viewport.clientHeight-PRESTIGE_CANVAS.height*scale)/2})},[]);
 const focusTree=useCallback(()=>{const viewport=treeRef.current;if(!viewport)return;const scale=clampScale(Math.max(.52,Math.min(.72,viewport.clientWidth/620)));setMapView({scale,x:viewport.clientWidth/2-PRESTIGE_CANVAS.core.x*scale,y:12})},[]);
 const zoomMap=(factor:number)=>{const viewport=treeRef.current;if(!viewport)return;setMapView(view=>{const scale=clampScale(view.scale*factor),cx=viewport.clientWidth/2,cy=viewport.clientHeight/2;return{scale,x:cx-(cx-view.x)*scale/view.scale,y:cy-(cy-view.y)*scale/view.scale}})};
 const mapPointerDown=(event:ReactPointerEvent<HTMLDivElement>)=>{event.currentTarget.setPointerCapture(event.pointerId);pointers.current.set(event.pointerId,{x:event.clientX,y:event.clientY});const points=[...pointers.current.values()];gesture.current=points.length===2?{distance:Math.hypot(points[0].x-points[1].x,points[0].y-points[1].y),center:{x:(points[0].x+points[1].x)/2,y:(points[0].y+points[1].y)/2},view:mapView}:null};
 const mapPointerMove=(event:ReactPointerEvent<HTMLDivElement>)=>{const previous=pointers.current.get(event.pointerId);if(!previous)return;const before=[...pointers.current.values()];pointers.current.set(event.pointerId,{x:event.clientX,y:event.clientY});const points=[...pointers.current.values()];if(points.length===1){setMapView(view=>({...view,x:view.x+event.clientX-previous.x,y:view.y+event.clientY-previous.y}));return}if(points.length===2&&gesture.current){const distance=Math.hypot(points[0].x-points[1].x,points[0].y-points[1].y),center={x:(points[0].x+points[1].x)/2,y:(points[0].y+points[1].y)/2},start=gesture.current,scale=clampScale(start.view.scale*distance/Math.max(1,start.distance));setMapView({scale,x:center.x-(start.center.x-start.view.x)*scale/start.view.scale,y:center.y-(start.center.y-start.view.y)*scale/start.view.scale})}};
