 useEffect(()=>{if(!selected)return;closeRef.current?.focus();const escape=(event:KeyboardEvent)=>{if(event.key==='Escape')setSelected(null)};window.addEventListener('keydown',escape);return()=>{window.removeEventListener('keydown',escape);returnFocus.current?.focus()}},[selected]);
 useEffect(()=>{if(!axiomConfirming)return;axiomDialogRef.current?.focus();const escape=(event:KeyboardEvent)=>{if(event.key==='Escape')setAxiomConfirming(false)};window.addEventListener('keydown',escape);return()=>{window.removeEventListener('keydown',escape);axiomTriggerRef.current?.focus()}},[axiomConfirming]);
